@extends('layouts.terminal') @section('title','Attendance Terminal')
@section('content')
<div x-data="terminal({{ Illuminate\Support\Js::from($employees) }})" class="min-h-screen bg-slate-950 p-4 text-white"><header class="mx-auto flex max-w-5xl items-center justify-between py-4"><div><p class="text-sm text-slate-300">Palma General Store</p><h1 class="text-xl font-semibold">Attendance Terminal</h1></div><div class="text-2xl tabular-nums" x-text="clock"></div><a href="{{ route('dashboard.index') }}" class="rounded-lg border border-slate-600 px-4 py-3 text-sm">Back to Dashboard</a></header><main class="mx-auto grid max-w-5xl gap-6 py-8 lg:grid-cols-2"><section class="rounded-2xl border border-slate-700 bg-slate-900 p-6 text-center"><div class="mx-auto mb-5 grid h-64 w-64 place-items-center rounded-2xl border-2 border-dashed border-slate-500 text-slate-400"><span x-text="state==='scanning'?'Scanning…':'QR scanner ready'"></span></div><h2 class="text-xl font-semibold" x-text="message"></h2><p class="mt-2 min-h-6 text-slate-300" x-text="result?.full_name||'Position your QR code in the camera frame.'"></p><button @click="scan()" :disabled="state!=='idle'" class="mt-6 min-h-11 min-w-44 rounded-xl bg-teal-700 px-6 py-3 font-semibold disabled:opacity-50" x-text="state==='scanning'?'Scanning…':'Start Scan'"></button></section><section class="rounded-2xl border border-slate-700 bg-slate-900 p-6"><button @click="manualOpen=!manualOpen" class="min-h-11 rounded-lg border border-slate-600 px-4 py-3">Manual Employee ID Entry</button><form x-show="manualOpen" @submit.prevent="lookup()" class="mt-5 space-y-3"><label class="block text-sm">Employee ID<input x-model="employeeId" required class="mt-1 min-h-11 w-full rounded-lg border border-slate-600 bg-slate-800 p-3 text-white" placeholder="EMP-0001"></label><button class="min-h-11 w-full rounded-lg bg-emerald-700 px-4 py-3 font-semibold">Submit</button></form><div x-show="result" class="mt-8 rounded-xl bg-slate-800 p-4"><p class="font-semibold" x-text="result?.full_name"></p><p class="text-sm text-slate-300" x-text="action"></p><button @click="record()" class="mt-3 min-h-11 w-full rounded-lg bg-emerald-700 p-3">Confirm <span x-text="action"></span></button></div></section></main></div>
<script>function terminal(people){return {people,clock:'',state:'idle',message:'Ready to scan',result:null,action:'',employeeId:'',manualOpen:false,openSessions:{},init(){this.tick();setInterval(()=>this.tick(),1000)},tick(){this.clock=new Date().toLocaleTimeString('en-PH',{timeZone:'Asia/Manila'})},scan(){this.state='scanning';this.message='Scanning QR code…';setTimeout(()=>{if(Math.random()<.1){this.state='error';this.message='QR code not recognized';this.reset()}else{this.lookup(this.people[Math.floor(Math.random()*this.people.length)].employee_id)}},2000)},lookup(id=this.employeeId){let p=this.people.find(e=>e.employee_id.toLowerCase()===id.toLowerCase());if(!p){this.state='error';this.message='Employee ID not found';this.reset();return}this.result=p;this.action=this.openSessions[p.employee_id]?'TIME OUT':'TIME IN';this.state='result';this.message='Employee verified'},record(){if(this.action==='TIME IN')this.openSessions[this.result.employee_id]=true;else delete this.openSessions[this.result.employee_id];this.message=this.action+' recorded';this.employeeId='';setTimeout(()=>{this.result=null;this.state='idle';this.message='Ready to scan'},3000)},reset(){setTimeout(()=>{this.state='idle';this.message='Ready to scan'},3000)}}}</script>
@endsection
